from dataclasses import dataclass
from datetime import datetime, timedelta


@dataclass
class _Appointment:
    patient: str
    doctor: str
    start: datetime
    end: datetime
    cancelled: bool = False
    blocked: bool = True


class Scheduler:
    def __init__(self) -> None:
        self._appointments: dict[int, _Appointment] = {}
        self._next_id = 1

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        if start >= end:
            raise ValueError("Appointment start must be before end")

        if any(
            appointment.patient == patient
            and not appointment.cancelled
            and appointment.start > now
            for appointment in self._appointments.values()
        ):
            raise ValueError("Patient already has an upcoming appointment")

        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not free during this interval")

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = _Appointment(
            patient, doctor, start, end
        )
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appointment = self._appointments.get(appointment_id)
        if appointment is None or appointment.cancelled:
            raise ValueError("Appointment does not exist or is already cancelled")

        appointment.cancelled = True
        if appointment.start - now >= timedelta(hours=24):
            appointment.blocked = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if start >= end:
            raise ValueError("Interval start must be before end")

        return not any(
            appointment.blocked
            and appointment.doctor == doctor
            and start < appointment.end
            and appointment.start < end
            for appointment in self._appointments.values()
        )
